function lang(v){return state.locale==='en'?tUI(v):v}
function translatedName(v){return state.locale==='en'?tUI(v):v}
function crumbHtml(){const current=currentSnapshot();let path=[...(state.navTrail||[]).map((s,i)=>({s,i,label:navLabel(s)})),{s:current,i:-1,label:navLabel(current)}];path=path.filter((x,i)=>i===0||x.s.page!==path[i-1].s.page||x.s.inboxId!==path[i-1].s.inboxId||x.s.agentId!==path[i-1].s.agentId);let hidden=[];if(path.length>4){hidden=path.slice(1,-2);path=[path[0],{more:true},...path.slice(-2)]}return `<div class="route-crumbs"><button class="route-back" data-action="nav-back" title="${lang('Назад')}" aria-label="${lang('Назад')}">${I('back',16)}</button><div class="crumb-track">${path.map((x,i)=> x.more?`<button class="crumb-more" data-action="crumb-more" title="${lang('Показать путь')}">…</button>`:`${i?`<span class="crumb-sep">${I('arrow',11)}</span>`:''}<button class="crumb-item ${x.i===-1?'current':''}" data-action="crumb-go" data-index="${x.i}" ${x.i===-1?'aria-current="page"':''} title="${esc(x.label)}">${esc(x.label)}</button>`).join('')}</div></div>`}
function profileMenuHtml(){const org=currentOrg();const organizations=state.organizations.map(o=>`<button class="profile-menu-row ${o.id===org.id?'chosen':''}" data-action="switch-org" data-id="${esc(o.id)}">${I('building',16)}<span><strong>${esc(o.name)}</strong><small>${esc(o.role)} · ${esc(o.plan)}</small></span>${o.id===org.id?I('check',15):''}</button>`).join('');return `<div class="profile-menu" role="menu"><div class="profile-menu-head">${lang('Организации')}</div>${organizations}<button class="profile-menu-row" data-action="new-org">${I('plus',16)}<span>${lang('Создать организацию')}</span></button><div class="profile-menu-line"></div><button class="profile-menu-row" data-action="open-profile">${I('users',16)}<span>${lang('Мой профиль')}</span></button><button class="profile-menu-row" data-action="open-profile-help">${I('help',16)}<span>${lang('Справка и поддержка')}</span></button><button class="profile-menu-row" data-action="switch-account">${I('back',16)}<span>${lang('Войти в другой аккаунт')}</span></button><button class="profile-menu-row exit" data-action="logout">${I('close',16)}<span>${lang('Выйти')}</span></button></div>`}
function accountView(){const org=currentOrg();return `<div class="account-screen"><div class="account-inner panel pad"><div class="brand account-brand"><div class="brand-icon">a.</div><div class="brand-name">AIMock</div></div><h1>${lang('Вход в AIMock')}</h1><p class="muted">${lang('Войдите в аккаунт, чтобы продолжить работу.')}</p><label class="field-label">Email</label><input class="field" id="account-email" type="email" value="alexander@example.com"/><label class="field-label">${lang('Пароль')}</label><input class="field" id="account-password" type="password" placeholder="••••••••"/><button class="btn primary block mt16" data-action="account-signin">${lang('Войти')}</button><button class="btn flat block mt12" data-action="account-register">${lang('Создать аккаунт')}</button></div></div>`}
function profilePage(){const org=currentOrg();return `<div class="profile-detail"><h1>${lang('Мой профиль')}</h1><div class="panel pad"><div class="flex align gap12 mb16"><span class="avatar">АМ</span><div><h2>${lang('Александр Морозов')}</h2><p class="small muted">alexander@example.com</p></div></div><div class="grid-even"><div><label class="field-label">${lang('Имя')}</label><input class="field" value="${lang('Александр Морозов')}" readonly/></div><div><label class="field-label">Email</label><input class="field" value="alexander@example.com" readonly/></div><div><label class="field-label">${lang('Язык интерфейса')}</label><div class="subline">${state.locale==='ru'?'Русский':'English'}</div></div><div><label class="field-label">${lang('Организация')}</label><div class="subline">${esc(org.name)} · ${lang(org.role)}</div></div></div></div></div>`}
function contactDetailPage(){const c=state.conversations.find(x=>x.id===state.contactContext);if(!c)return `<div class="empty">${lang('Контакт не найден')}</div>`;const a=state.agents.find(x=>x.id===c.agentId);const candidate=state.candidates.find(x=>x.name===c.name);return `<div class="profile-detail"><h1>${esc(translatedName(c.name))}</h1><div class="panel pad"><div class="flex align gap12 mb20"><span class="avatar">${esc(c.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><strong>${a?.type==='hr'?lang('Кандидат'):lang('Контакт')}</strong><p class="muted small">${esc(c.channel)} · ${esc(a?.name||'')}</p></div></div><div class="grid-even"><div class="meta-block"><small>${lang('Ответственный')}</small><strong>${c.owner==='human'?lang('Сотрудник'):lang('ИИ-сотрудник')}</strong></div><div class="meta-block"><small>${lang('Источник')}</small><strong>${esc(c.channel)}</strong></div></div><div class="flex gap8 mt20"><button class="btn primary" data-action="contact-to-chat" data-id="${c.id}">${lang('Открыть диалог')}</button>${candidate?`<button class="btn" data-action="open-candidate" data-id="${candidate.id}">${lang('Карточка кандидата')}</button>`:''}</div></div></div>`}
function journalDetailPage(){let e=state.events.find(x=>x.id===state.eventContext);if(!e&&String(state.eventContext||'').startsWith('message:')){const c=state.conversations.find(x=>x.id===state.journalContext),m=c?.messages[Number(state.eventContext.split(':')[1])];if(m)e={title:m.by==='contact'?'Получено сообщение':m.by==='ai'?'Ответ ИИ':'Ответ сотрудника',desc:m.text,date:'18.10.2026',time:m.time,cost:'—',duration:'—'}}return `<div class="profile-detail"><h1>${lang('Событие')}</h1><div class="panel pad"><h2>${esc(e?.title||lang('Событие'))}</h2><p class="muted mt12">${esc(e?.desc||'')}</p><div class="grid-even mt20"><div class="meta-block"><small>${lang('Время')}</small><strong>${esc(e?.date||'')} ${esc(e?.time||'')}</strong></div><div class="meta-block"><small>${lang('Длительность')}</small><strong>${esc(e?.duration||'—')}</strong></div><div class="meta-block"><small>${lang('Списано')}</small><strong>${esc(e?.cost||'—')}</strong></div></div><button class="btn mt20" data-action="nav-back">${I('back',14)} ${lang('Назад')}</button></div></div>`}
function extraDialog(){const x=state.utilityModal;if(!x)return '';if(x==='new-org')return `<div class="modal-backdrop"><div class="modal panel"><h2>${lang('Создать организацию')}</h2><p class="thin-note mt12">${lang('Новая организация получит отдельный тариф, сотрудников, агентов и баланс.')}</p><div class="form-row mt20"><label class="field-label">${lang('Название организации')}</label><input class="field" id="org-create-name" autofocus placeholder="${lang('Название организации')}"/></div><div class="flex gap8 mt16"><button class="btn primary" data-action="org-create-confirm">${lang('Создать')}</button><button class="btn" data-action="utility-close">${lang('Отмена')}</button></div></div></div>`;if(x==='login-other'||x==='logout')return `<div class="modal-backdrop"><div class="modal panel"><h2>${x==='logout'?lang('Выйти из аккаунта?'):lang('Войти в другой аккаунт')}</h2><p class="thin-note mt12">${lang('Все организации этого аккаунта останутся привязаны к нему.')}</p><div class="flex gap8 mt20"><button class="btn primary" data-action="account-signout">${x==='logout'?lang('Выйти'):lang('Продолжить')}</button><button class="btn" data-action="utility-close">${lang('Отмена')}</button></div></div></div>`;if(x==='crumb-more')return `<div class="modal-backdrop"><div class="modal panel"><h2>${lang('История переходов')}</h2>${state.navTrail.map((s,i)=>`<button class="profile-menu-row" data-action="crumb-go" data-index="${i}">${esc(navLabel(s))}</button>`).join('')}<button class="btn mt16" data-action="utility-close">${lang('Закрыть')}</button></div></div>`;return ''}

function render(){const nav=state.mode==='workspace'?workspaceNav:adminNav;const active=state.mode==='admin'&&(!state.page.startsWith('admin-'))?'admin-overview':state.mode==='workspace'&&state.page.startsWith('admin-')?'overview':state.page;state.page=active;const num=state.notifications.filter(x=>!x.read).length;const org=currentOrg();const body=state.accountSignedOut?accountView():`<div class="shell ${state.mode==='workspace'?'workspace-skin':''} ${state.mode==='workspace'&&active==='overview'?'overview-shell':''} ${state.sidebar?'menu-open':''}"><div class="drawer-overlay" data-action="menu"></div><aside class="side"><div class="brand"><div class="brand-icon">a<span style="font-size:12px;margin-left:-2px">.</span></div><div class="brand-name">AIMock</div></div><div class="nav">${nav.map(x=>`<button class="nav-btn ${active===x[0]?'active':''}" data-action="navigate" data-page="${x[0]}" data-hint="${esc(lang(x[1]))}" aria-label="${esc(lang(x[1]))}" title="${esc(lang(x[1]))}"><span class="nav-ico">${I(x[2],19)}</span><span class="nav-label">${x[1]}</span>${x[0]==='notifications'&&num?`<span class="nav-count">${num}</span>`:''}</button>`).join('')}</div><div class="side-foot"><button class="side-profile profile-trigger" data-action="profile-toggle" aria-label="${esc(lang("Александр Морозов"))} · ${esc(org.name)}" title="${esc(lang("Мой профиль"))} · ${esc(org.name)}" aria-haspopup="menu" aria-expanded="${Boolean(state.profileOpen)}"><span class="avatar">АМ</span><span class="profile-txt"><strong>Александр Морозов</strong><small>${state.mode==='admin'?'Platform owner':esc(org.name)+' · '+esc(org.role)}</small></span>${I('arrow',14)}</button>${state.profileOpen?profileMenuHtml():''}</div></aside><main class="main"><header class="topbar"><div class="flex align gap8"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Открыть меню">${I('menu',17)}</button>${crumbHtml()}</div><div class="top-actions"><div class="demo-switch"><button data-action="mode" data-mode="workspace" class="${state.mode==='workspace'?'current':''}">Workspace</button><button data-action="mode" data-mode="admin" class="${state.mode==='admin'?'current':''}">Admin</button></div><button class="icon-btn theme-button" data-action="toggle-theme" title="Theme" aria-label="Theme">${state.theme==='dark'?'☀':'☾'}</button><button class="icon-btn lang-button" data-action="toggle-locale" title="Language" aria-label="Language">${state.locale==='ru'?'EN':'RU'}</button>${state.mode==='workspace'?`<button data-action="go-notifications" class="icon-btn" aria-label="Уведомления">${I('bell',17)}${num?'<span class="dot"></span>':''}</button>`:''}</div></header><div class="workspace ${state.page==='inbox'?'workspace-inbox':''}">${state.mode==='workspace'?banner():''}<div class="view-stage ${state.page==='overview'||state.page==='admin-overview'?'home-view':'flow-view'}">${state.mode==='workspace'?workspacePage():adminPage()}</div></div></main></div>`;app.innerHTML=body+(state.modal?renderModal():'')+extraDialog();document.body.setAttribute('data-theme',state.theme);document.documentElement.lang=state.locale;translateRenderedUI();restoreScroll();save()}
function workspacePage(){switch(state.page){case 'overview':return overview();case 'agents':return agentsPage();case 'agent':return agentPage();case 'inbox':return inboxPage();case 'approvals':return approvalsPage();case 'contacts':return contactsPage();case 'contact-detail':return contactDetailPage();case 'profile':return profilePage();case 'journal-event':return journalDetailPage();case 'knowledge':return knowledgePage();case 'integrations':return integrationPage();case 'analytics':return analyticsPage();case 'journal':return journalPage();case 'notifications':return notificationsPage();case 'help':return helpPage();case 'billing':return billingPage();case 'settings':return settingsPage();default:return overview()}}
// Workspace Overview is implemented in src/overview.js (loaded before app.js).
function agentsPage(){const q=state.search.toLowerCase();const agents=state.agents.filter(a=>(a.name+' '+a.tags.join(' ')+' '+badgeType(a.type)).toLowerCase().includes(q));return `${head('ИИ-сотрудники','Все агенты компании в одном каталоге: продажи, рекрутинг и другие задачи.',button(`${I('plus',15)} Создать агента`,'new-agent','primary'))}<div class="toolbar"><div class="search">${I('search',15)}<input data-input="search" placeholder="Поиск по имени, типу или тегу" value="${esc(state.search)}" /></div><div class="flex gap8 align"><span class="badge blue">${state.agents.length} из 10</span>${button(`${I('filter',14)} Представления`,'views','sm')}</div></div><div class="agent-grid">${agents.map(a=>`<article class="panel agent-card" data-action="open-agent" data-id="${a.id}" tabindex="0" role="button"><div class="top"><div class="agent-icon">${I('bot',23)}</div>${statusBadge(a.status)}</div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><div class="tags"><span class="tag">${badgeType(a.type)}</span>${a.tags.map(t=>`<span class="tag">#${esc(t)}</span>`).join('')}</div><div class="card-footer"><div class="small muted">${esc(a.scope)}</div><span style="color:var(--blue)">${I('arrow',17)}</span></div></article>`).join('')}</div>${!agents.length?`<div class="empty">${I('search',27)}<h3>Ничего не найдено</h3><p>Попробуйте другое имя или тег.</p></div>`:''}`}
function agentPage(){const a=getAgent();const locked=a.status==='active'||(state.scenario==='wallet'&&a.status==='active');const subscribed=state.scenario!=='expired';const tabs=[['overview','Обзор'],['settings','Настройки'],['integrations','Интеграции'],['knowledge','Знания'],['test','Тестирование'],['history','Журнал'],...(a.type==='hr'?[['candidates','Кандидаты']]:[])];return `<button class="back" data-action="go-agents">${I('back',14)} Все агенты</button><div class="detail-head"><div class="detail-top"><div class="detail-ico">${I('bot',27)}</div><div><div class="flex align gap8">${statusBadge(a.status)}<span class="badge">${badgeType(a.type)}</span></div><h1>${esc(a.name)}</h1><div class="small muted">${esc(a.scope)} · ${esc(a.tags.map(t=>'#'+t).join(' '))}</div></div></div><div class="detail-actions">${a.status==='active'?button(`${I('stop',15)} Остановить агента`,'stop-agent','danger',`data-id="${a.id}"`):button(`${I('play',15)} Запустить агента`,'start-agent','primary',`data-id="${a.id}" ${!subscribed?'disabled':''}`)}</div></div><div class="pill-tabs">${tabs.map(t=>`<button data-action="agent-tab" data-tab="${t[0]}" class="${state.agentTab===t[0]?'active':''}">${t[1]}</button>`).join('')}</div>${a.status==='active'&&['settings','integrations','knowledge'].includes(state.agentTab)?`<div class="locked">${I('lock',19)}<div><strong>Этот агент работает — конфигурация доступна только для чтения.</strong><br/>Чтобы изменить инструкции, знания или назначение интеграций, сначала остановите агента. Зависимые ресурсы также защищены.</div></div>`:''}${state.agentTab==='overview'?agentOverview(a):state.agentTab==='settings'?agentSettings(a,locked||!subscribed):state.agentTab==='integrations'?agentIntegrations(a,locked||!subscribed):state.agentTab==='knowledge'?agentKnowledge(a,locked||!subscribed):state.agentTab==='test'?agentTest(a):state.agentTab==='history'?journalPage(true):candidateBoard(true)}`}
function agentOverview(a){return `<div class="metrics">${metric('Обработано диалогов',a.dialogs,'За всё время · пример','message')}${metric('Расход ИИ',rMoney(a.spent),'Клиентские списания','wallet')}${metric('Подключения',String(a.connectors.length),'Назначены агенту','plug')}${metric('Последняя активность',a.last,'По журналу','clock')}</div><div class="grid-even">${panel(`<div class="panel-head"><div><h2>Назначенные интеграции</h2><p>Зависимые подключения</p></div>${button('Настроить','agent-integrations','sm')}</div>${a.connectors.map(id=>{const c=getConnector(id);return c?`<div class="list-row"><span class="avatar">${I('plug')}</span><div class="grow"><strong>${esc(c.name)}</strong><p>${esc(c.type)}</p></div><span class="badge green">Доступно</span></div>`:''}).join('')||'<div class="thin-note">Нет подключённых интеграций.</div>'}`,'pad')}${panel(`<div class="panel-head"><div><h2>Действия и правила</h2><p>Система исполняет только разрешённые операции</p></div></div><div class="divided"><div class="flex between align"><span class="small">Ручной перехват диалога</span><span class="badge green">Разрешён</span></div><div class="flex between align"><span class="small">Автоматический кадровый отказ</span><span class="badge red">Запрещён</span></div><div class="flex between align"><span class="small">Редактирование работающего агента</span><span class="badge ${a.status==='active'?'amber':'green'}">${a.status==='active'?'Заблокировано':'Доступно'}</span></div></div>`,'pad')}</div>`}
function agentSettings(a,locked){return `<div class="grid-two">${panel(`<div class="panel-head"><div><h2>Конфигурация агента</h2><p>У остановленного агента поля автоматически сохраняются.</p></div><span class="badge ${locked?'amber':'green'}">${locked?'Только чтение':'Черновик'}</span></div><div class="form-row"><label class="field-label">Имя сотрудника</label><input class="field" data-agent-field="name" data-agent="${a.id}" value="${esc(a.name)}" ${locked?'disabled':''}/></div><div class="form-row"><label class="field-label">Описание задач</label><textarea class="textarea" data-agent-field="description" data-agent="${a.id}" ${locked?'disabled':''}>${esc(a.description)}</textarea></div><div class="form-row"><label class="field-label">Системные инструкции</label><textarea style="min-height:145px" class="textarea" data-agent-field="prompt" data-agent="${a.id}" ${locked?'disabled':''}>${esc(a.prompt)}</textarea></div><div class="form-row"><label class="field-label">Теги (через запятую)</label><input class="field" data-agent-field="tags" data-agent="${a.id}" value="${esc(a.tags.join(', '))}" ${locked?'disabled':''}/></div><div class="page-state">${I(locked?'lock':'check',14)} ${locked?'Редактирование заблокировано, пока агент активен':'Изменения сохраняются  автоматически'}</div>`,'pad')}${panel(`<h2>Управление жизненным циклом</h2><p class="thin-note mt8">Активный агент использует неизменяемую конфигурацию. Остановка необходима перед любыми изменениями его рабочих настроек.</p><div class="selected-box mt20"><strong class="small">Текущий статус</strong><div class="mt8">${statusBadge(a.status)}</div><p class="thin-note mt12">Все сохранённые поля синхронизируются в рабочем пространстве организации.</p></div>`,'pad')}</div>`}
function agentIntegrations(a,locked){return `<div class="grid-two">${panel(`<div class="panel-head"><div><h2>Подключения агента</h2><p>Каналы одному агенту, CRM и календарь могут быть общими</p></div>${button(`${I('plus',14)} Добавить подключение`,'go-integrations','sm')}</div>${state.connectors.map(c=>{const used=c.agentId&&c.agentId!==a.id;const disabled=locked||(c.kind==='exclusive'&&used);const assigned=a.connectors.includes(c.id);return `<div class="connector ${c.kind==='exclusive'&&used?'locked-c':''}"><div class="agent-icon" style="width:35px;height:35px">${I(c.type.includes('CRM')?'chart':c.type.includes('Календарь')?'calendar':'message',18)}</div><div class="grow"><strong class="small">${esc(c.name)}</strong><p class="tiny muted mt8">${c.kind==='exclusive'?'Эксклюзивный канал':'Совместное подключение'}${used?' · занят: '+esc(getAgent(c.agentId).name):''}</p></div><span class="badge ${assigned?'green':''}">${assigned?'Назначено':used?'Занято':'Свободно'}</span><input aria-label="Назначить интеграцию ${esc(c.name)}" type="checkbox" class="check" data-connector-id="${c.id}" data-agent="${a.id}" ${assigned?'checked':''} ${disabled?'disabled':''}/></div>`}).join('')}`,'pad')}${panel(`<h2>Правила назначения</h2><div class="divided mt12"><div><strong class="small">Боты и каналы общения</strong><p class="thin-note mt8">Может использовать только один агент. При занятости виден его владелец.</p></div><div><strong class="small">CRM / календари</strong><p class="thin-note mt8">Разрешены нескольким агентам, если назначены необходимые действия.</p></div><div><strong class="small">Активный агент</strong><p class="thin-note mt8">Изменение подключений запрещено до остановки агента.</p></div></div>`,'pad')}</div>`}
function agentKnowledge(a,locked){return `${panel(`<div class="panel-head"><div><h2>База знаний агента</h2><p>Документы и их содержимое доступны только для чтения во время работы агента.</p></div>${button(`${I('plus',14)} Загрузить документ`,'upload-knowledge','sm',locked?'disabled':'')}</div><div class="list-row"><span class="avatar">${I('file')}</span><div class="grow"><strong>Частые вопросы.pdf</strong><p>Ответы на типовые вопросы · общий ресурс</p></div><span class="badge">Назначен</span>${locked?I('lock',16):''}</div><div class="list-row"><span class="avatar">${I('book')}</span><div class="grow"><strong>Справочник компании</strong><p>Политики и инструкции · используется агентом</p></div><span class="badge">Назначен</span>${locked?I('lock',16):''}</div><div class="thin-note mt16">Редактирование файлов, используемых активными агентами, недоступно до их остановки.</div>`,'pad')}`}
function agentTest(a){const live=state.testMode==='live';return `<div class="grid-two">${panel(`<div class="panel-head"><div><h2>Тестирование</h2><p>Проверьте диалог и действия агента перед запуском</p></div><span class="badge blue">Plus</span></div><div class="mini-tabs mb16"><button class="${!live?'active':''}" data-action="test-mode" data-mode="safe">Симуляция</button><button class="${live?'active':''}" data-action="test-mode" data-mode="live">Реальные интеграции</button></div>${live?`<div class="notice"><span>${I('alert',20)}</span><div><strong>LIVE-тест · требуется подтверждение каждого действия</strong><p>Каждое внешнее действие требует отдельного подтверждения перед отправкой в подключённый сервис.</p></div></div>`:`<div class="notice info">${I('shield',20)}<div><strong>Безопасная симуляция</strong><p>Никакие интеграции и реальные данные не изменяются.</p></div></div>`}<div class="test-chat"><div class="test-messages">${state.testMessages.length?state.testMessages.map(m=>`<div class="test-message"><span class="badge blue">TEST</span> ${esc(m.text)}</div>`).join(''):`<div class="empty">${I('message',28)}<h3>Начните тестовый диалог</h3><p>Напишите, что вы хотите проверить в работе агента.</p></div>`}</div><div class="test-input"><input class="field" id="test-input" placeholder="Например: создай сделку в CRM" ${state.scenario==='expired'?'disabled':''}/>${button(I('send',16),'send-test','primary',state.scenario==='expired'?'disabled':'')}</div></div>`,'pad')}${panel(`<h2>Как работает тестирование</h2><div class="divided mt12"><div><strong class="small">Free</strong><p class="thin-note mt8">10 сообщений на агента за всё время, суммарный бюджет 100 на организацию. Внешние действия симулируются.</p></div><div><strong class="small">Plus</strong><p class="thin-note mt8">Симуляция или LIVE. Прежде чем выполнить каждое реальное действие, агент показывает запрос на подтверждение.</p></div><div><strong class="small">Метки</strong><p class="thin-note mt8">Тестовые сообщения и операции помечаются TEST в журнале и Inbox.</p></div><div><strong class="small">Прозрачность расходов</strong><p class="thin-note mt8">Виден фактический расход клиента, а не название модели или внутренняя трасса.</p></div></div>`,'pad')}</div>`}
function inboxPage(){const rows=state.conversations.filter(c=>(state.inboxFilter==='all'||state.inboxFilter==='mine'&&c.owner==='human'||state.inboxFilter==='hr'&&getAgent(c.agentId)?.type==='hr'||state.inboxFilter==='sales'&&getAgent(c.agentId)?.type==='sales')&&(!state.inboxQuery||(c.name+' '+c.last+' '+c.channel).toLowerCase().includes(state.inboxQuery.toLowerCase())));const chat=state.conversations.find(c=>c.id===state.inboxId)||state.conversations[0];if(!chat)return `<div class="inbox-full empty-inbox"><div class="empty">${I('message',28)}<h2>${lang('Нет диалогов')}</h2><p>${lang('Новые сообщения появятся здесь, когда агенты начнут работу.')}</p></div></div>`;const agent=getAgent(chat.agentId);const human=chat.owner==='human';const restricted=state.scenario==='expired';return `<div class="inbox-full ${state.showMobileDetails?'show-details':''}"><div class="inbox-left"><div class="inbox-left-head"><div class="flex between align mb16"><h2>Все диалоги</h2><span class="badge blue">${state.conversations.length}</span></div><input class="field inbox-query" data-input="inbox-search" placeholder="Поиск по диалогам" value="${esc(state.inboxQuery||'')}"/><select data-change="inbox-filter"><option value="all" ${state.inboxFilter==='all'?'selected':''}>Все диалоги</option><option value="mine" ${state.inboxFilter==='mine'?'selected':''}>Мои / у сотрудников</option><option value="hr" ${state.inboxFilter==='hr'?'selected':''}>Рекрутинг</option><option value="sales" ${state.inboxFilter==='sales'?'selected':''}>Продажи</option></select></div><div class="chat-scroll">${rows.map(c=>`<button class="chat-item ${chat.id===c.id?'active':''}" data-action="chat-select" data-id="${c.id}"><span class="avatar ${getAgent(c.agentId)?.type==='hr'?'pink':''}">${esc(c.name.split(' ').map(p=>p[0]).slice(0,2).join(''))}</span><span class="content"><span class="meta"><strong>${esc(c.name)}</strong><time>${esc(c.time)}</time></span><p>${esc(c.last)}</p><span class="flex gap8 mt8"><span class="badge">${esc(c.channel)}</span><span class="badge ${c.owner==='human'?'amber':'blue'}">${c.owner==='human'?'Сотрудник':'ИИ'}</span></span></span></button>`).join('')||`<p class="empty">${lang('Нет диалогов по фильтру')}</p>`}</div></div><div class="chat-center"><div class="chat-top"><div><h3>${esc(chat.name)}</h3><div class="tiny muted mt8">${esc(chat.channel)} · ${esc(agent?.name||'')}</div></div><button class="chat-details-toggle icon-btn" data-action="toggle-chat-details" aria-label="${lang('Детали обращения')}">${I('users',16)}</button>${human?button('Вернуть ИИ','return-chat','sm',`data-id="${chat.id}"`):button('Взять диалог','takeover-chat','primary sm',`data-id="${chat.id}"`)}</div><div class="chat-messages"><div class="thread-note">История диалога · все сообщения</div>${chat.messages.map(m=>`<div class="bubble-row ${m.by!=='contact'?'outgoing':''}"><div class="bubble">${esc(m.text)}<div class="bubble-meta">${m.by==='contact'?'Клиент':m.by==='ai'?'ИИ-сотрудник':'Сотрудник'} · ${esc(m.time)}</div></div></div>`).join('')}</div><div class="chat-composer"><input class="field" id="chat-input" placeholder="${restricted?'Переписка недоступна после grace':human?'Написать ответ от лица сотрудника…':'Сначала возьмите диалог в работу'}" ${!human||restricted?'disabled':''}/>${button(I('send',16),'send-message','primary',!human||restricted?'disabled':'')}</div></div><div class="inbox-right"><div class="inbox-right-top"><h2>Детали обращения</h2><button class="chat-details-close icon-btn" data-action="toggle-chat-details" aria-label="${lang('Закрыть')}">${I('close',15)}</button><span class="badge">${esc(chat.channel)}</span></div><div class="meta-block mt16"><small>Контакт</small><button class="context-link" data-action="conversation-contact" data-id="${chat.id}">${esc(chat.name)} ${I('arrow',15)}</button></div><div class="meta-block"><small>ИИ-сотрудник</small><button class="context-link" data-action="conversation-agent" data-id="${agent?.id||''}">${esc(agent?.name||'—')} ${I('arrow',15)}</button></div><div class="meta-block"><small>Ответственный</small><strong>${human?'Ольга К. · ручной режим':'ИИ-сотрудник'}</strong></div><div class="meta-block"><small>Ветка</small><strong>${agent?.type==='hr'?'Рекрутинг':'Продажи'}</strong></div><div class="meta-block"><small>Переписка и действия</small>${button('Открыть журнал','conversation-journal','sm',`data-id="${chat.id}"`)}</div></div></div>`}
function approvalsPage(){return `${head('Согласования','Все операции, ожидающие решения сотрудника, с проверкой его полномочий.')}${panel(`<div class="list-row"><span class="avatar orange">${I('clipboard')}</span><div class="grow"><strong>Предварительный вердикт по кандидату</strong><p>Дмитрий Орлов · Рекрутер · Стройка · требуется решение HR</p></div>${button('Рассмотреть','open-candidate','primary sm',`data-id="k3"`)}</div><div class="list-row"><span class="avatar">${I('message')}</span><div class="grow"><strong>Ручное управление диалогом</strong><p>Мария Соколова · уже передано сотруднику Ольге К.</p></div>${button('Открыть','go-inbox','sm')}</div><div class="notice info mt16">${I('shield',18)}<div><strong>LIVE-тестирование работает отдельно</strong><p>При каждом реальном действии агент запрашивает подтверждение прямо в тестовой сессии.</p></div></div>`,'pad')}`}
function candidateBoard(compact=false){const selected=state.candidateId?getCandidate():null;return `${!compact?head('Контакты и кандидаты','Единый реестр с разграничением доступа. Ниже — пример HR-представления.') : ''}<div class="toolbar"><div class="flex align gap8"><span class="badge blue">Вакансия: монтажники и прорабы</span><span class="badge">Рекрутер · Стройка</span></div>${button('Открыть сообщения','go-inbox','sm')}</div><div class="kanban">${[['review','На рассмотрение'],['possible','Потенциальный отказ']].map(([category,title])=>`<div class="lane"><div class="lane-head"><h3>${title}</h3><span class="badge">${state.candidates.filter(c=>c.category===category).length}</span></div>${state.candidates.filter(c=>c.category===category).map(c=>`<div class="candidate" data-action="open-candidate" data-id="${c.id}"><div class="flex between align"><strong>${esc(c.name)}</strong><span class="badge">${esc(c.channel)}</span></div><p>${esc(c.role)} · ${esc(c.stage)}</p><p>${esc(c.detail)}</p><div class="flex between align mt12"><span class="tiny muted">Решение только за HR</span><span style="color:var(--blue)">${I('arrow',14)}</span></div></div>`).join('')||'<div class="tiny muted">Нет кандидатов</div>'}</div>`).join('')}</div><div class="panel pad mt16"><h2>Правило безопасности рекрутинга</h2><p class="thin-note mt8">ИИ только сортирует по двум предварительным категориям. Никаких автономных отказов или найма: окончательное решение и внешнее уведомление — после действия HR.</p></div>`}
function contactsPage(){return candidateBoard(false)}
function knowledgePage(){return `${head('База знаний','Единые документы и знания организации с блокировкой ресурсов работающих агентов.',button(`${I('plus',15)} Добавить документ`,'upload-knowledge','primary'))}${panel(`<div class="list-row"><span class="avatar">${I('file')}</span><div class="grow"><strong>Частые вопросы.pdf</strong><p>Назначено: Менеджер продаж (активен)</p></div><span class="badge amber">${I('lock',12)} Только чтение</span>${button('Посмотреть','knowledge-details','sm')}</div><div class="list-row"><span class="avatar">${I('file')}</span><div class="grow"><strong>Требования к кандидатам.pdf</strong><p>Назначено: Рекрутер · Стройка (активен)</p></div><span class="badge amber">${I('lock',12)} Только чтение</span>${button('Посмотреть','knowledge-details','sm')}</div><div class="list-row"><span class="avatar">${I('file')}</span><div class="grow"><strong>Новое руководство.docx</strong><p>Пока не назначено агентам</p></div><span class="badge green">Редактирование доступно</span>${button('Посмотреть','knowledge-details','sm')}</div>`,'pad')}`}
function integrationPage(){const used=(c)=>c.kind==='exclusive'&&c.agentId?getAgent(c.agentId).name:state.agents.filter(a=>a.connectors.includes(c.id)).map(a=>a.name).join(', ')||'Не назначено';return `${head('Интеграции','Общий каталог подключений компании. Каналы эксклюзивны, CRM и календари совместные.',button(`${I('plus',15)} Добавить интеграцию`,'add-connector','primary'))}<div class="flex align gap8 mb16"><span class="badge blue">${state.connectors.length} / 10 подключений</span><span class="badge green">${state.connectors.filter(c=>c.status==='ok').length} работают</span></div>${panel(`<div class="table-wrap"><table class="table"><thead><tr><th>Подключение</th><th>Тип</th><th>Правило</th><th>Назначение</th><th>Статус</th></tr></thead><tbody>${state.connectors.map(c=>`<tr class="clickable" data-action="connector-detail" data-id="${c.id}"><td class="primary-cell">${esc(c.name)}</td><td>${esc(c.type)}</td><td>${c.kind==='exclusive'?'<span class="badge amber">1 агент</span>':'<span class="badge blue">Несколько агентов</span>'}</td><td>${esc(used(c))}</td><td>${statusBadge(c.status)}</td></tr>`).join('')}</tbody></table></div>`)}<p class="thin-note mt16">Для изменения назначения интеграции остановите агента. Состояние каждого подключения доступно в его карточке.</p>`}
function journalPage(compact=false){const context=state.journalContext?state.conversations.find(c=>c.id===state.journalContext):null;let events=compact?state.events.filter(x=>x.agentId===state.agentId):context?state.events.filter(e=>e.conversationId===context.id||e.desc?.includes(context.name)):state.events;const inferred=context?context.messages.map((m,i)=>({id:'message:'+i,time:m.time,date:'18.10.2026',title:m.by==='contact'?'Получено сообщение':m.by==='ai'?'Ответ ИИ':'Ответ сотрудника',desc:`${context.name} · ${context.channel} · ${m.text}`,type:m.by==='contact'?'integration':m.by,duration:'—',cost:'—'})):[];if(context)events=[...events,...inferred];return `<div class="journal-page">${compact?'':`<div class="journal-head"><h1>${context?`${lang('Журнал диалога')}: ${esc(context.name)}`:lang('Журнал действий')}</h1>${context?button(`${I('back',14)} ${lang('Вернуться к переписке')}`,'journal-to-chat','sm',`data-id="${context.id}"`):''}</div>`}<div class="panel pad"><div class="panel-head"><div><h2>${lang('Хронология событий')}</h2></div><span class="badge">${events.length} ${lang('событий')}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>${lang('Время')}</th><th>${lang('Событие')}</th><th>${lang('Тип')}</th><th>${lang('Длительность')}</th><th>${lang('Списано')}</th></tr></thead><tbody>${events.map(e=>`<tr class="clickable" data-action="open-event" data-id="${e.id}"><td>${esc(e.date)}<br/><span class="muted">${esc(e.time)}</span></td><td class="primary-cell">${esc(e.title)}<div class="small muted mt8">${esc(e.desc)}</div></td><td><span class="badge ${e.type==='test'?'blue':e.type==='human'?'amber':''}">${e.type==='test'?'TEST':e.type==='ai'?'ИИ':e.type==='human'?'Сотрудник':'Интеграция'}</span></td><td>${esc(e.duration)}</td><td>${esc(e.cost)}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function notificationsPage(){return `${head('Уведомления','Важные события на сайте и по подтверждённой электронной почте.',button(`${I('check',14)} Отметить все прочитанными`,'read-all','sm'))}<div class="grid-two">${panel(`<div class="panel-head"><div><h2>Центр уведомлений</h2><p>Новое уведомление не означает автоматически выполненную задачу</p></div><span class="badge blue">${state.notifications.filter(n=>!n.read).length} новых</span></div>${state.notifications.map(n=>`<div class="list-row"><span class="avatar ${n.type==='billing'?'orange':n.type==='action'?'pink':''}">${I(n.type==='billing'?'wallet':n.type==='action'?'clipboard':'message',17)}</span><div class="grow"><strong>${esc(n.title)} ${n.read?'':'<span class="badge blue">Новое</span>'}</strong><p>${esc(n.desc)} · ${esc(n.time)}</p></div>${button(n.read?'Открыть':'Прочитать',n.read?'notif-open':'notif-read','sm',`data-id="${n.id}"`)}</div>`).join('')}`,'pad')}${panel(`<h2>Email-уведомления</h2><p class="thin-note mt8">Критические сообщения поступают на сайт и подтверждённую почту независимо от открытого браузера.</p><div class="form-row mt20"><label class="field-label">Email организации</label><input class="field" id="notify-email" value="${esc(state.notifyEmail)}" /></div><div class="flex align gap8 mb16"><span class="badge ${state.emailVerified?'green':'amber'}">${state.emailVerified?'Адрес подтверждён':'Требуется подтверждение'}</span></div>${button('Изменить адрес','save-email','sm block')}<div class="divided mt12"><div class="small">Подписка и 48-часовой период</div><div class="small">Недостаток AI-средств</div><div class="small">Требуется решение HR или менеджера</div><div class="small">Критическая ошибка интеграции</div></div><p class="thin-note mt16">Историю доставки и ошибки отправки можно просмотреть в журнале уведомлений.</p>`,'pad')}</div>`}
function analyticsPage(){return `${head('Аналитика','Единые показатели по агентам, обращениям и каналам.') }<div class="metrics">${metric('Всего диалогов','247','За текущий месяц','message')}${metric('AI-действий','812','Успешно: 98%','bot')}${metric('Ручные перехваты','32','По рабочим диалогам','users')}${metric('Расходы на ИИ','423,90 ₽','Клиентская стоимость','wallet')}</div><div class="grid-even">${panel(`<h2>По типам агентов</h2><div class="mt20"><div class="bar-label"><span>Продажи</span><strong>68%</strong></div><div class="progress"><span style="width:68%"></span></div></div><div class="mt20"><div class="bar-label"><span>Рекрутинг</span><strong>32%</strong></div><div class="progress green"><span style="width:32%"></span></div></div>`,'pad')}${panel(`<h2>По каналам</h2><div class="mt20"><div class="bar-label"><span>Telegram</span><strong>52%</strong></div><div class="progress"><span style="width:52%"></span></div></div><div class="mt20"><div class="bar-label"><span>MAX</span><strong>31%</strong></div><div class="progress green"><span style="width:31%"></span></div></div><div class="mt20"><div class="bar-label"><span>Виджет сайта</span><strong>17%</strong></div><div class="progress amber"><span style="width:17%"></span></div></div>`,'pad')}</div>`}
function helpPage(){const topics=[['Создание ИИ-сотрудника','Как настроить черновик, интеграции, тестирование и запуск'],['Интеграции и подключения','Как создать бота и назначить его одному агенту'],['Сообщения и перехват диалога','Как отвечать клиентам из AIMock'],['Тестирование LIVE','Подтверждение каждого реального действия'],['Финансы и льготный период','Баланс ИИ, оплата и 48 часов после окончания подписки'],['Рекрутинг и кандидаты','Предварительные категории и окончательное решение HR']];let q=state.helpSearch.toLowerCase();return `${head('Справка и обучение','Практические инструкции по работе с AIMock; не путать с знаниями, загружаемыми для агентов.') }<div class="search mb16" style="max-width:470px">${I('search',15)}<input data-input="helpSearch" placeholder="Поиск по инструкциям" value="${esc(state.helpSearch)}" /></div><div class="box-grid">${topics.filter(t=>t.join(' ').toLowerCase().includes(q)).map(t=>`<button class="quick-action" data-action="help-topic" data-title="${esc(t[0])}"><span style="color:var(--blue)">${I('book',22)}</span><strong>${esc(t[0])}</strong><p>${esc(t[1])}</p></button>`).join('')}</div><div class="thin-note mt20">Статьи регулярно обновляются и доступны в центре помощи.</div>`}
function billingPage(){return `${head('Финансы','Тариф, средства на работу ИИ, расходы и история оплаты.',button(`${I('plus',14)} Пополнить AI-баланс`,'topup','primary'))}<div class="metrics">${metric('Текущий тариф','Plus','900 ₽ / месяц','credit')}${metric('AI-баланс','1 850 ₽','Отдельно от подписки','wallet')}${metric('Расходы за месяц','423,90 ₽','Списания за период','activity')}${metric('Интеграции',state.connectors.length+'/10','Лимит организации','plug')}</div><div class="grid-even">${panel(`<div class="panel-head"><div><h2>Подписка</h2><p>Условия текущего тарифа</p></div><span class="badge green">Активна</span></div><div class="divided"><div class="flex between align"><span class="small muted">Тариф</span><strong>Plus</strong></div><div class="flex between align"><span class="small muted">Следующая оплата</span><strong>21 октября 2026</strong></div><div class="flex between align"><span class="small muted">Льготный период</span><strong>48 часов</strong></div></div><p class="thin-note mt16">После окончания оплаченного срока функции работают ещё 48 часов, при достаточном AI-балансе. Далее — только просмотр, оплата и поддержка.</p>${button('Управлять подпиской','manage-sub','sm mt16')}`,'pad')}${panel(`<h2>Последние операции</h2><div class="list-row"><span class="avatar green">${I('plus')}</span><div class="grow"><strong>Пополнение AI-баланса</strong><p>10 октября 2026</p></div><strong>+2 000 ₽</strong></div><div class="list-row"><span class="avatar">${I('bot')}</span><div class="grow"><strong>Использование ИИ</strong><p>18 октября 2026 · Менеджер продаж</p></div><strong>−0,24 ₽</strong></div><div class="list-row"><span class="avatar">${I('credit')}</span><div class="grow"><strong>Подписка Plus</strong><p>21 сентября 2026</p></div><strong>−900 ₽</strong></div>`,'pad')}</div><div class="panel pad mt16"><h2>Проверка режимов ограничения</h2><p class="thin-note mt8">Состояние подписки определяет доступность функций и работу агентов. </p><div class="mt16 select-row"><select data-change="scenario"><option value="active" ${state.scenario==='active'?'selected':''}>Подписка активна</option><option value="grace" ${state.scenario==='grace'?'selected':''}>Grace · 48 часов</option><option value="wallet" ${state.scenario==='wallet'?'selected':''}>AI-баланс исчерпан</option><option value="expired" ${state.scenario==='expired'?'selected':''}>После grace · только просмотр</option></select>${button('Посмотреть сообщения','go-inbox','sm')}</div></div>`}
function settingsPage(){return `${head('Настройки','Организация, участники, доступы и уведомления.') }<div class="grid-even">${panel(`<h2>Организация</h2><div class="form-row mt20"><label class="field-label">Название</label><input class="field" value="Норд Групп" disabled /></div><div class="form-row"><label class="field-label">Моя роль</label><input class="field" value="Владелец · полный доступ" disabled /></div><h3>Команда и доступы</h3><div class="divided"><div class="flex between align"><span class="small">Участники организации</span><span class="badge">6 из 20</span></div><div class="flex between align"><span class="small">Настраиваемые роли</span>${button('Просмотр ролей','roles','sm')}</div><div class="flex between align"><span class="small">Группы доступа</span>${button('Просмотр групп','groups','sm')}</div></div>`,'pad')}${panel(`<h2>Уведомления</h2><p class="thin-note mt8">Все важные события приходят в интерфейс и по подтверждённому email.</p><div class="form-row mt20"><label class="field-label">Адрес организации</label><input class="field" value="${esc(state.notifyEmail)}" disabled /></div><div class="mb16">${state.emailVerified?'<span class="badge green">Подтверждён</span>':'<span class="badge amber">Не подтверждён</span>'}</div>${button('Настроить уведомления','go-notifications','primary sm')}`,'pad')}</div>`}
function adminPage(){switch(state.page){case 'admin-overview':return adminOverview();case 'admin-users':return adminUsers();case 'admin-orgs':return adminOrgs();case 'admin-org-detail':return adminOrgDetail();case 'admin-plans':return adminPlans();case 'admin-ai':return adminAI();case 'admin-connectors':return adminConnectors();case 'admin-promos':return adminPromos();case 'admin-support':return adminSupport();case 'admin-analytics':return adminAnalytics();case 'admin-system':return adminSystem();default:return adminOverview()}}
function adminOverview(){
return `<div class="ov-dashboard admin-dashboard"><div class="ov-heading"><div><div class="ov-overline">AIMOCK / PLATFORM CONTROL <span class="ov-live"><b></b> Только </span></div><h1>Панель управления <span class="ov-wave">✳</span></h1><p>Показатели продукта, организации и финансовые события.</p></div><div class="ov-heading-actions">${button(`${I('building',16)} Организации`,'go-admin-orgs','primary')}${button('Отчёты','go-admin-analytics','')}</div></div>
<div class="ov-kpis"><button class="ov-kpi ov-kpi-lavender" data-action="go-admin-users"><div class="ov-kpi-top"><span>Аккаунтов</span><i>${I('users',18)}</i></div><strong>1 284</strong><small>+92 за 30 дней</small></button><button class="ov-kpi ov-kpi-mint" data-action="go-admin-orgs"><div class="ov-kpi-top"><span>Организации</span><i>${I('building',18)}</i></div><strong>846</strong><small>Все тарифы платформы</small></button><button class="ov-kpi ov-kpi-cream" data-action="go-admin-plans"><div class="ov-kpi-top"><span>Платные подписки</span><i>${I('credit',18)}</i></div><strong>312</strong><small>Plus и другие тарифы</small></button><button class="ov-kpi ov-kpi-blue" data-action="go-admin-analytics"><div class="ov-kpi-top"><span>MRR</span><i>${I('chart',18)}</i></div><strong>280 800 <em>₽</em></strong><small>Ежемесячная выручка</small></button></div>
<div class="ov-content"><section class="ov-panel ov-graph"><div class="ov-panel-head"><div><h2>Рост платных подписок</h2><p>Статистика по данным платформы</p></div><span class="ov-trend">↑ 12,8%</span></div><div class="ov-graph-inner"><div class="ov-graph-stat"><strong>312</strong><small>активных подписок</small><span class="ov-muted-pill">Free: 534 · Plus: 312</span></div><div class="ov-bar-chart">${[29,40,38,52,54,73,81].map((v,i)=>`<div class="ov-bar-col"><div class="ov-bar-back"><span style="height:${v}%" class="${i===6?'peak':''}"></span></div><small>${['Апр','Май','Июн','Июл','Авг','Сен','Окт'][i]}</small></div>`).join('')}</div></div><div class="ov-card-bottom"><span>${I('shield',14)} История изменения показателей</span>${button('Вся аналитика →','go-admin-analytics','flat sm')}</div></section>
<section class="ov-panel ov-feature admin-feature"><div class="ov-feature-decoration ov-feature-decoration-one"></div><div class="ov-feature-decoration ov-feature-decoration-two"></div><span class="ov-feature-icon">${I('shield',20)}</span><div class="ov-feature-content"><div class="ov-feature-label">AIMOCK ADMIN</div><h2>Вся платформа.<br/>Одна точка контроля.</h2><p>Тарифы, модели, использование и поддержка клиентов.</p><button data-action="go-admin-orgs" class="ov-feature-button">Управлять организациями ${I('arrow',16)}</button></div></section>
<section class="ov-panel ov-agents"><div class="ov-panel-head"><div><h2>Последние организации</h2><p>Состояние и баланс компаний</p></div>${button('Все →','go-admin-orgs','flat sm')}</div><div class="ov-agent-list">${state.orgs.map(o=>`<button class="ov-agent-line" data-action="org-detail" data-id="${o.id}"><span class="ov-agent-glyph">${I('building',18)}</span><span class="ov-agent-text"><strong>${esc(o.name)}</strong><small>${o.running} работающих агентов · ${rMoney(o.balance)}</small></span>${statusBadge(o.status)}${I('arrow',14)}</button>`).join('')}</div></section>
<section class="ov-panel ov-attention"><div class="ov-panel-head"><div><h2>Оперативные события</h2><p>Действия, которые требуют проверки</p></div><span class="badge amber">2 события</span></div><div class="ov-attention-items"><button class="ov-task" data-action="go-admin-orgs"><span class="ov-task-icon warm">${I('clock',17)}</span><span><strong>Льготный период</strong><small>Атлас Групп · нужна оплата</small></span>${I('arrow',14)}</button><button class="ov-task" data-action="go-admin-support"><span class="ov-task-icon cool">${I('headphones',17)}</span><span><strong>Запрос на возврат</strong><small>Требуется финансовая проверка</small></span>${I('arrow',14)}</button><button class="ov-task" data-action="go-admin-ai"><span class="ov-task-icon violet">${I('brain',17)}</span><span><strong>AI-конфигурация</strong><small>Одна активная модель для всех клиентов</small></span>${I('arrow',14)}</button></div></section></div></div>`;
}
function adminUsers(){return `${head('Пользователи','Системные аккаунты платформы и их связь с организациями.')}${panel(`<div class="table-wrap"><table class="table"><thead><tr><th>Пользователь</th><th>Организация</th><th>Роль</th><th>Статус</th></tr></thead><tbody>${[['Алексей С.','Норд Групп','Owner'],['Мария П.','Атлас Групп','Owner'],['Ольга К.','Норд Групп','HR'],['Дмитрий Л.','Техно Маркет','Owner']].map(x=>`<tr><td class="primary-cell">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td><span class="badge green">Активен</span></td></tr>`).join('')}</tbody></table></div><p class="thin-note mt16">Системный администратор может управлять блокировкой учётных записей и аудитом действий.</p>`,'pad')}`}
function adminOrgs(){return `${head('Организации','Все компании: подписки, агенты, остатки и история работы.')}${panel(`<div class="table-wrap"><table class="table"><thead><tr><th>Организация</th><th>Тариф</th><th>Состояние</th><th>Агенты</th><th>AI-баланс</th><th></th></tr></thead><tbody>${state.orgs.map(o=>`<tr class="clickable" data-action="org-detail" data-id="${o.id}"><td class="primary-cell">${esc(o.name)}</td><td>${esc(o.plan)}</td><td>${statusBadge(o.status)}</td><td>${o.running} / ${o.agents} активны</td><td>${rMoney(o.balance)}</td><td>${I('arrow',15)}</td></tr>`).join('')}</tbody></table></div>`)}<div class="notice info mt16">${I('shield',18)}<div><strong>Конфиденциальность организаций</strong><p>В Admin доступны технические и финансовые метаданные, но не произвольное содержимое резюме и частных диалогов.</p></div></div>`}
function adminOrgDetail(){const o=state.orgs.find(x=>x.id===state.adminOrgId)||state.orgs[0];const tabs=[['overview','Обзор'],['agents','Агенты'],['finance','Финансы'],['activity','Активность'],['refund','Возвраты']];return `<button class="back" data-action="go-admin-orgs">${I('back',14)} Все организации</button><div class="detail-head"><div><div class="flex align gap8">${statusBadge(o.status)}<span class="badge">${esc(o.plan)}</span></div><h1 class="mt12">${esc(o.name)}</h1><p class="small muted mt8">Организация в AIMock · служебный контекст</p></div>${button(o.status==='blocked'?'Снять блокировку':'Заблокировать организацию','org-block','danger',`data-id="${o.id}"`)}</div><div class="metrics">${metric('Агенты в работе',o.running+'/'+o.agents,'Статусы доступны владельцу Admin','bot')}${metric('AI-баланс',rMoney(o.balance),'Предоплаченный остаток','wallet')}${metric('Потребление ИИ',rMoney(o.spent),'За период · пример','activity')}${metric('Тариф',o.plan,o.status==='grace'?'48-часовой льготный период':'Контроль подписки','credit')}</div><div class="pill-tabs">${tabs.map(t=>`<button class="${state.adminTab===t[0]?'active':''}" data-action="admin-tab" data-tab="${t[0]}">${t[1]}</button>`).join('')}</div>${state.adminTab==='overview'?panel(`<h2>Сведения об организации</h2><div class="divided mt12"><div class="flex between align"><span class="small muted">Владелец</span><strong>Алексей С. ()</strong></div><div class="flex between align"><span class="small muted">Сотрудники</span><strong>6</strong></div><div class="flex between align"><span class="small muted">Тариф</span><strong>${o.plan}</strong></div><div class="flex between align"><span class="small muted">Подписка</span>${statusBadge(o.status)}</div></div><p class="thin-note mt16">Для расчёта возврата доступны журнал операций, статус агентов, подписочные платежи и отдельный AI-кошелёк. Содержимое пользовательских переписок автоматически не раскрывается.</p>`,'pad'):state.adminTab==='agents'?panel(`<div class="panel-head"><h2>ИИ-сотрудники организации</h2><span class="badge">Работают: ${o.running}</span></div>${(o.id==='org1'?state.agents:[{name:'Менеджер клиентских заявок',status:o.running?'active':'stopped'},{name:'Рекрутер вакансий',status:o.running>1?'active':'stopped'}]).map(a=>`<div class="list-row"><span class="avatar">${I('bot')}</span><div class="grow"><strong>${esc(a.name)}</strong><p>Журнал и операционные сведения доступны для проверки</p></div>${statusBadge(a.status)}</div>`).join('')}`,'pad'):state.adminTab==='finance'?panel(`<h2>Финансовый контур</h2><div class="grid-even mt20"><div class="selected-box"><div class="small muted">Подписка</div><h2 class="mt8">${esc(o.plan)} · 900 ₽/мес.</h2><p class="thin-note mt8">Условия тарифа и история оплат</p></div><div class="selected-box"><div class="small muted">AI-кошелёк</div><h2 class="mt8">${rMoney(o.balance)}</h2><p class="thin-note mt8">Отдельный остаток и ledger</p></div></div><div class="list-row mt20"><span class="avatar green">${I('credit')}</span><div class="grow"><strong>Подписка · подтверждённая оплата</strong><p>21 сентября 2026</p></div><strong>900 ₽</strong></div><div class="list-row"><span class="avatar">${I('activity')}</span><div class="grow"><strong>Расходы AI-кошелька</strong><p>По журналу использования</p></div><strong>${rMoney(o.spent)}</strong></div>`,'pad'):state.adminTab==='activity'?panel(`<h2>История работы и использования</h2><p class="thin-note mt8">Просмотр технических событий и финансовых сумм; без автоматического доступа к текстам диалогов.</p><div class="event-list mt20">${state.events.slice(0,4).map(e=>`<div class="event"><span class="event-dot"></span><div><strong>${esc(e.title)}</strong><p>${esc(e.desc)}</p></div><span class="event-time">${esc(e.time)}</span></div>`).join('')}</div>`,'pad'):panel(`<div class="panel-head"><div><h2>Оформление возврата</h2><p>Раздельная проверка подписки и AI-кошелька</p></div></div><div class="notice">${I('alert',19)}<div><strong>${o.running>0?`Работают ${o.running} агента(ов)`:'Нет активных агентов'}</strong><p>Перед финансовым расчётом проверьте состояние агентов и возможность дополнительных списаний. Возврат требует учёта условий договора и платежей.</p></div></div><div class="cols-two"><div><label class="field-label">Запрос на возврат, ₽</label><input id="refund-amount" type="number" min="0" class="field" value="450"/></div><div><label class="field-label">Источник</label><select id="refund-source"><option>Подписка</option><option>AI-кошелёк</option></select></div></div><div class="form-row mt16"><label class="field-label">Основание</label><textarea id="refund-reason" class="textarea">Запрос клиента: частичный возврат</textarea></div>${button('Проверить расчёт · ','refund-preview','primary',`data-id="${o.id}"`)}<p class="thin-note mt16">Операции возврата фиксируются в журнале и сверяются с платёжным провайдером.</p>`,'pad')}`}
function adminPlans(){return `${head('Тарифы и подписки','Цена, возможности и лимиты полностью управляются через системную Admin.',button(`${I('plus',14)} Новый тариф`,'new-plan','primary'))}<div class="grid-even">${state.plans.map(p=>panel(`<div class="flex between align"><h2>${esc(p.name)}</h2><span class="badge ${p.name==='Plus'?'blue':''}">План</span></div><div class="metric-value">${rMoney(p.price)}<span class="small muted"> / мес.</span></div><div class="divided mt12"><div class="flex between align"><span class="small muted">Агенты</span><strong>${p.agents}</strong></div><div class="flex between align"><span class="small muted">Сотрудники</span><strong>${p.members}</strong></div><div class="flex between align"><span class="small muted">Интеграции</span><strong>${p.integrations}</strong></div></div>${button('Изменить тариф','edit-plan','sm mt16',`data-id="${esc(p.name)}"`)}`,'pad')).join('')}</div><div class="notice info mt16">${I('clock',19)}<div><strong>Версии тарифов и уведомления клиентов</strong><p>Новая цена действующего тарифа вступает в силу при следующей оплате. Клиент заранее увидит сумму и дату изменения. Показанные суммы — гипотезы.</p></div></div>`}
function adminAI(){const names=['Основная модель · Yandex AI Studio','Резервная модель · пример адаптера','Дополнительная модель · пример каталога'];return `${head('ИИ и модели','Выбор провайдера и модели только в Admin. Одновременно активна одна конфигурация.')}${panel(`<div class="notice info">${I('brain',20)}<div><strong>Одна активная модель для всей платформы</strong><p>Выбор в админке не раскрывается организациям. Смена модели влияет на будущие задачи; текущие выполнения сохраняют свою версию конфигурации.</p></div></div>${names.map(n=>`<div class="list-row"><span class="avatar">${I('brain')}</span><div class="grow"><strong>${esc(n)}</strong><p>${n.includes('Yandex')?'Первоначальный провайдер · поддерживаемый адаптер':'Доступна для настройки'}</p></div>${state.adminAiModel===n?'<span class="badge green">Активна</span>':button('Выбрать','switch-model','sm',`data-model="${esc(n)}"`)}</div>`).join('')}<p class="thin-note mt16">Смена активной модели требует успешной проверки совместимости и подтверждения системного администратора.</p>`,'pad')}`}
function adminConnectors(){return `${head('Коннекторы','Здоровье внешних интеграционных адаптеров и политика их возможностей.')}${panel(`${['Telegram Bot','MAX Bot','CRM','Календарь','VK / WhatsApp / Viber · по мере доступности'].map(t=>`<div class="list-row"><span class="avatar">${I('plug')}</span><div class="grow"><strong>${esc(t)}</strong><p>Доступность зависит от официальных API, прав и развернутого адаптера</p></div><span class="badge ${t.includes('по мере')?'amber':'green'}">${t.includes('по мере')?'Поэтапно':'Доступен'}</span></div>`).join('')}`,'pad')}`}
function adminPromos(){return `${head('Промокоды','Создание кодов и уникальных ссылок, воронка переходов → регистрации → оплаты.',button(`${I('plus',14)} Создать промокод`,'new-promo','primary'))}${panel(`<div class="table-wrap"><table class="table"><thead><tr><th>Код</th><th>Скидка</th><th>Переходы</th><th>Регистрации</th><th>Оплаты</th><th>Ссылка</th></tr></thead><tbody>${state.promos.map(p=>`<tr><td class="primary-cell">${esc(p.code)}</td><td>${p.discount}%</td><td>${p.clicks}</td><td>${p.signups}</td><td>${p.payments}</td><td>${button('Скопировать','copy-promo','sm',`data-code="${esc(p.code)}"`)}</td></tr>`).join('')}</tbody></table></div><p class="thin-note mt16">Данные обновляются после обработки событий переходов, регистраций и платежей.</p>`)} `}
function adminSupport(){return `${head('Поддержка AIMock','Обращения пользователей с организационным контекстом и журналом ответов.') }<div class="grid-two">${panel(`<div class="panel-head"><div><h2>Запрос №SUP-1042</h2><p>Запрос на возврат · открыт</p></div><span class="badge amber">Ожидает ответа</span></div><div class="support-chat"><div class="reply"><span class="badge">Клиент</span><p class="mt8">Здравствуйте. Хочу уточнить возможность возврата. Почти не пользовались агентами.</p></div>${state.supportReplies.map(text=>`<div class="reply from-admin"><span class="badge blue">AIMock Admin</span><p class="mt8">${esc(text)}</p></div>`).join('')}</div><div class="chat-composer" style="padding-left:0;padding-right:0;margin-top:12px"><input class="field" id="support-input" placeholder="Ответить клиенту…"/>${button(I('send',15),'send-support','primary')}</div>`,'pad')}${panel(`<h2>Контекст клиента</h2><div class="divided mt16"><div><span class="small muted">Автор запроса</span><strong style="display:block;margin-top:6px">Алексей С.</strong></div><div><span class="small muted">Организация</span><strong style="display:block;margin-top:6px">Норд Групп</strong></div><div><span class="small muted">Тариф / баланс</span><strong style="display:block;margin-top:6px">Plus · 1 850 ₽</strong></div><div><span class="small muted">Работающие агенты</span><strong style="display:block;margin-top:6px">2 из 3</strong></div></div>${button('Открыть карточку организации','org-detail','sm mt16',`data-id="org1"`)}<p class="thin-note mt16">Содержимое переписок клиента скрыто от поддержки по умолчанию. Доступны только разрешённые сведения для диагностики.</p>`,'pad')}</div>`}
function adminAnalytics(){return `${head('Аналитика SaaS','Подписки, использование, выручка, конверсии и удержание.') }<div class="metrics">${metric('MRR','280 800 ₽','За текущий месяц','chart')}${metric('Free → Plus','8,7%','Конверсия · пример','credit')}${metric('Активные организации','312','Платные подписки','building')}${metric('Grace','19','Не считать оплаченной выручкой','clock')}</div>${panel(`<h2>Выручка и использование</h2><div class="faux-chart" style="height:260px">${[42,44,55,62,69,75,84,90].map((h,i)=>`<div class="chart-bar" style="height:${h}%"><i>${i+1}</i></div>`).join('')}</div><p class="thin-note mt20">Показатели рассчитываются по подтверждённым финансовым операциям и записям учёта.</p>`,'pad')}`}
function adminSystem(){return `${head('Система и аудит','Глобальные политики, контроль безопасности и протокол действий системных администраторов.')}${panel(`<div class="notice info">${I('shield',19)}<div><strong>Системное управление отделено от Workspace</strong><p>Тарифы, ограничения, уведомления, модели и политики меняются через Admin. Базовые проверки безопасности нельзя выключить настройкой.</p></div></div><div class="list-row"><span class="avatar">${I('clock')}</span><div class="grow"><strong>Продолжительность льготного периода</strong><p>Оплаченная подписка → grace → только просмотр</p></div><span class="badge blue">48 часов</span></div><div class="list-row"><span class="avatar">${I('bell')}</span><div class="grow"><strong>Критические уведомления</strong><p>Email + сайт · шаблоны и пороги</p></div><span class="badge green">Включены</span></div><div class="list-row"><span class="avatar">${I('shield')}</span><div class="grow"><strong>Аварийная остановка исходящих AI-операций</strong><p>Только системному владельцу · аудит</p></div>${button('Просмотреть процедуру','emergency','danger sm')}</div>`,'pad')}`}
function renderModal(){const m=state.modal;let title='',body='',footer='';const x=button('Отмена','modal-close','');switch(m.type){
case 'new-agent':title='Создать ИИ-сотрудника';body=`<p class="thin-note mb16">Создайте черновик. Назначения и инструкции можно изменить до запуска.</p><div class="form-row"><label class="field-label">Название агента</label><input id="new-agent-name" class="field" placeholder="Например, Менеджер поддержки" autofocus/></div><div class="form-row"><label class="field-label">Тип агента</label><select id="new-agent-type"><option value="sales">Менеджер</option><option value="hr">Рекрутер</option></select></div>`;footer=x+button('Создать черновик','create-agent','primary');break;
case 'add-connector':title='Добавить интеграцию';body=`<p class="thin-note mb16">Создайте подключение в общем Integration Hub. Эксклюзивность определяется типом ресурса.</p><div class="form-row"><label class="field-label">Название подключения</label><input class="field" id="connector-name" placeholder="Например, Telegram · Поддержка" /></div><div class="form-row"><label class="field-label">Тип подключения</label><select id="connector-type"><option>Telegram Bot</option><option>MAX Bot</option><option>CRM</option><option>Календарь</option><option>Email</option></select></div><div class="notice info">${I('shield',16)}<div><strong> Настройки доступа</strong><p>Подключение появится в каталоге после успешной проверки прав доступа.</p></div></div>`;footer=x+button('Добавить в каталог','create-connector','primary');break;
case 'stop-agent':{const a=getAgent(m.id);title='Остановить агента?';body=`<div class="notice">${I('alert',19)}<div><strong>${esc(a.name)}</strong><p>Агент перестанет автоматически отвечать. Клиенту не отправляется сообщение об остановке. Входящие по возможности сохраняются.</p></div></div><p class="thin-note">После остановки станут доступны его настройки и связанные ресурсы. Запуск выполняется вручную.</p>`;footer=x+button('Да, остановить','confirm-stop','danger');break}
case 'start-agent':{const a=getAgent(m.id);title='Запустить ИИ-сотрудника?';body=`<p class="thin-note">Будут проверены статус подписки, баланс, права и обязательные настройки.</p><div class="selected-box mt16"><strong>${esc(a.name)}</strong><p class="thin-note mt8">${a.connectors.length} назначенных интеграций · текущая версия черновика</p></div>`;footer=x+button('Запустить ()','confirm-start','primary');break}
case 'confirm-test':{const a=getAgent();title='TEST · подтвердить внешнее действие';body=`<div class="notice">${I('alert',19)}<div><strong>Агент предлагает реальную операцию</strong><p>В полноценном AIMock без вашего разрешения она не будет выполнена. Операция будет выполнена после подтверждения.</p></div></div><div class="divided"><div><span class="field-label">Исполнитель</span><strong>${esc(a.name)}</strong></div><div><span class="field-label">Операция</span><strong>Создать тестовую сделку в CRM</strong></div><div><span class="field-label">Данные</span><strong>${esc(m.text||'Тестовый запрос')}</strong></div><div><span class="field-label">Среда</span><span class="badge blue">TEST</span></div></div>`;footer=x+button('Разрешить действие','approve-test','primary');break}
case 'candidate':{const c=getCandidate(m.id);title=c.name;body=`<div class="flex align gap8 mb16"><span class="badge">${esc(c.role)}</span><span class="badge ${c.category==='possible'?'amber':'green'}">${c.category==='possible'?'Потенциальный отказ':'На рассмотрение'}</span></div><div class="selected-box"><strong class="small">Предварительный анализ ИИ</strong><p class="thin-note mt8">${esc(c.detail)}</p></div><div class="divided mt16"><div class="flex between align"><span class="small muted">Стадия заявки</span><strong class="small">${esc(c.stage)}</strong></div><div class="flex between align"><span class="small muted">Выбранный канал</span><strong class="small">${esc(c.channel)}</strong></div></div><p class="thin-note mt16">Итоговое решение принимает HR. Внешнее уведомление отправляется только после ручного подтверждения ( не отправляется).</p>`;footer=x+button('Отказать · HR','candidate-reject','danger')+button('Продолжить отбор','candidate-accept','primary');break}
case 'candidate-reject':{const c=getCandidate(m.id);title='Подтвердить отказ кандидату';body=`<div class="notice">${I('alert',18)}<div><strong>Окончательное кадровое решение</strong><p>Его принимает HR, не ИИ. После подтверждения в рабочем продукте будет направлено уведомление через разрешённый канал.</p></div></div><div class="selected-box"><strong>${esc(c.name)}</strong><p class="thin-note mt8">${esc(c.role)} · ${esc(c.channel)}</p></div>`;footer=x+button('Вернуться','candidate-back')+button('Подтвердить отказ ()','candidate-reject-final','danger');break}
case 'connector':{const c=getConnector(m.id);title=c.name;const assigned=c.kind==='exclusive'&&c.agentId?getAgent(c.agentId).name:state.agents.filter(a=>a.connectors.includes(c.id)).map(a=>a.name).join(', ')||'Не назначено';body=`<div class="divided"><div class="flex between align"><span class="small muted">Тип</span><strong class="small">${esc(c.type)}</strong></div><div class="flex between align"><span class="small muted">Назначение</span><strong class="small">${esc(assigned)}</strong></div><div class="flex between align"><span class="small muted">Политика</span><strong class="small">${c.kind==='exclusive'?'Только один агент':'Совместное использование'}</strong></div></div><p class="thin-note mt16">Для изменения используйте вкладку «Интеграции» остановленного агента. Реальные секреты и API  не настраиваются.</p>`;footer=button('Понятно','modal-close','primary');break}
case 'edit-plan':{const p=state.plans.find(p=>p.name===m.id);title='Редактор тарифа: '+p.name;body=`<div class="cols-two"><div class="form-row"><label class="field-label">Цена, ₽ / месяц</label><input class="field" type="number" id="plan-price" value="${p.price}" min="0" /></div><div class="form-row"><label class="field-label">Агенты</label><input class="field" type="number" id="plan-agents" value="${p.agents}" min="1" /></div><div class="form-row"><label class="field-label">Сотрудники</label><input class="field" type="number" id="plan-members" value="${p.members}" min="1" /></div><div class="form-row"><label class="field-label">Интеграции</label><input class="field" type="number" id="plan-integrations" value="${p.integrations}" min="0" /></div></div><div class="notice info">${I('clock',18)}<div><strong>Новая версия тарифа</strong><p>В реальном Admin изменения условий требуют публикации и уведомления клиентов перед следующим платежом.</p></div></div>`;footer=x+button('Сохранить изменения ()','save-plan','primary');break}
case 'new-plan':title='Новый тариф';body=`<div class="form-row"><label class="field-label">Название</label><input class="field" id="plan-name" placeholder="Business" /></div><div class="form-row"><label class="field-label">Цена в месяц, ₽</label><input class="field" id="plan-price" type="number" min="0" value="1990" /></div>`;footer=x+button('Создать тариф ()','create-plan','primary');break;
case 'new-promo':title='Новый промокод';body=`<div class="form-row"><label class="field-label">Код</label><input class="field" id="promo-name" placeholder="AUTUMN25" /></div><div class="form-row"><label class="field-label">Скидка, %</label><input class="field" id="promo-discount" type="number" min="1" max="100" value="15" /></div>`;footer=x+button('Создать ()','create-promo','primary');break;
case 'refund-preview':{const o=state.orgs.find(x=>x.id===m.id);title='Проверка расчёта возврата';body=`<div class="notice">${I('alert',19)}<div><strong>${esc(o.name)}</strong><p>${o.running} работающих агента(ов). Проверьте договорные основания и остановите расходы до окончательного расчёта.</p></div></div><div class="divided"><div class="flex between align"><span class="small muted">Запрошено к возврату</span><strong>${rMoney(m.amount)}</strong></div><div class="flex between align"><span class="small muted">Источник</span><strong>${esc(m.source)}</strong></div><div class="flex between align"><span class="small muted">Остаток AI-баланса</span><strong>${rMoney(o.balance)}</strong></div></div><p class="thin-note mt16"> не производит реальный возврат. В рабочем продукте необходимы полномочия, ledger, расчёт и подтверждение платёжного провайдера.</p>`;footer=x+button('Создать заявку ()','refund-demo','primary');break}
case 'org-block':{const o=state.orgs.find(x=>x.id===m.id);title=o.status==='blocked'?'Снять блокировку?':'Заблокировать организацию?';body=`<p class="thin-note">Организация: <strong>${esc(o.name)}</strong>. При блокировке все ИИ-агенты останавливаются, Workspace доступен только для просмотра. После разблокировки их запускают вручную.</p>`;footer=x+button('Подтвердить ()','org-block-confirm','danger');break}
case 'model':title='Опубликовать конфигурацию ИИ?';body=`<div class="notice">${I('brain',20)}<div><strong>${esc(m.name)}</strong><p>Перед публикацией новой модели проверьте совместимость и влияние на новые задачи. Клиенты не видят сведения о провайдере.</p></div></div>`;footer=x+button('Выбрать ()','model-confirm','primary');break;
case 'generic':title=esc(m.title||'Сценарий');body=`<p class="thin-note">${esc(m.desc||'Здесь будет соответствующий экран или действие в полной реализации. В этом прототипе мы проверяем структуру и пользовательский сценарий.')}</p>`;footer=button('Понятно','modal-close','primary');break;
}
return `<div class="modal-backdrop" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal"><div class="modal-head"><div><h2>${title}</h2></div><button class="icon-btn" data-action="modal-close" aria-label="Закрыть">${I('close',16)}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${footer}</div></div></div>`}
const val=(id)=>document.getElementById(id)?.value??'';
const openGeneric=(title,desc)=>{state.modal={type:'generic',title,desc};render()};
function navigate(page,opts={}){scrollSave();const before=currentSnapshot();const changed=before.page!==page||opts.force;if(changed&&!opts.replace)state.navTrail=[...(state.navTrail||[]),before].slice(-24);state.page=page;state.sidebar=false;state.modal=null;state.profileOpen=false;state.utilityModal=null;if(opts.clearSearch)state.search='';render();writeHistory(Boolean(opts.replace))}
function navigateBack(){if(history.state?.aimockV04&&state.navTrail?.length){history.back();return}const prev=state.navTrail.pop();if(prev){restoreSnapshot(prev);writeHistory(true)}}
function runAction(act,el){const id=el?.dataset.id;if(act==='toggle-theme'){state.theme=state.theme==='dark'?'light':'dark';render();return}
if(act==='ov2-period'){state.ov2Period=Number(el.dataset.days)===30?30:7;render();return}
if(act==='ov2-tab'){state.ov2MobileTab=el.dataset.tab;render();return}
if(act==='ov2-open-event'){state.eventContext=id;navigate('journal-event');return}
if(act==='ov2-open-candidate'){state.candidateId=id;state.modal={type:'candidate',id};render();return}
if(act==='go-approvals'){navigate('approvals');return}
if(act==='toggle-locale'){state.locale=state.locale==='ru'?'en':'ru';render();return}
if(act==='toggle-chat-details'){state.showMobileDetails=!state.showMobileDetails;render();return}
if(act==='profile-toggle'){state.profileOpen=!state.profileOpen;render();return}
if(act==='switch-org'){switchOrganization(id);return}
if(act==='new-org'){state.profileOpen=false;state.utilityModal='new-org';render();return}
if(act==='org-create-confirm'){const name=document.getElementById('org-create-name')?.value.trim();if(!name){toast(lang('Введите название организации'));return}const id='org'+Date.now();state.organizations.push({id,name,plan:'Free',role:'Владелец'});state.utilityModal=null;switchOrganization(id);return}
if(act==='utility-close'){state.utilityModal=null;render();return}
if(act==='open-profile'){state.profileOpen=false;navigate('profile');return}
if(act==='open-profile-help'){state.profileOpen=false;navigate('help');return}
if(act==='switch-account'){state.profileOpen=false;state.utilityModal='login-other';render();return}
if(act==='logout'){state.profileOpen=false;state.utilityModal='logout';render();return}
if(act==='account-signout'){state.accountSignedOut=true;state.utilityModal=null;state.profileOpen=false;render();return}
if(act==='account-signin'||act==='account-register'){state.accountSignedOut=false;state.utilityModal=null;state.profileOpen=false;state.mode='workspace';navigate('overview',{replace:true});return}
if(act==='nav-back'){navigateBack();return}
if(act==='crumb-go'){const i=Number(el.dataset.index);state.utilityModal=null;if(i===-1)return;const snap=state.navTrail[i];if(snap){state.navTrail=state.navTrail.slice(0,i);restoreSnapshot(snap);writeHistory(false)}return}
if(act==='crumb-more'){state.utilityModal='crumb-more';render();return}
if(act==='conversation-journal'){state.journalContext=id;state.eventContext=null;navigate('journal');return}
if(act==='journal-to-chat'||act==='contact-to-chat'){state.inboxId=id;state.journalContext=null;navigate('inbox');return}
if(act==='conversation-contact'){state.contactContext=id;navigate('contact-detail');return}
if(act==='conversation-agent'){state.agentId=id;state.agentTab='overview';navigate('agent');return}
if(act==='open-event'){state.eventContext=id;navigate('journal-event');return}
switch(act){
case 'navigate':if(el.dataset.page==='journal')state.journalContext=null;navigate(el.dataset.page);break;
case 'mode':if(state.mode!==el.dataset.mode){state.mode=el.dataset.mode;state.page=state.mode==='admin'?'admin-overview':'overview';state.modal=null;state.navTrail=[];state.sidebar=false;state.profileOpen=false;render();writeHistory(true)}break;
case 'menu':state.sidebar=!state.sidebar;render();break;
case 'go-agents':navigate('agents');break;case 'go-inbox':state.journalContext=null;navigate('inbox');break;case 'go-journal':state.journalContext=null;navigate('journal');break;case 'go-billing':navigate('billing');break;case 'go-notifications':navigate('notifications');break;case 'go-settings':navigate('settings');break;case 'go-contacts':navigate('contacts');break;case 'go-integrations':navigate('integrations');break;
case 'go-admin-orgs':navigate('admin-orgs');break;case 'go-admin-support':navigate('admin-support');break;case 'go-admin-users':navigate('admin-users');break;case 'go-admin-plans':navigate('admin-plans');break;case 'go-admin-analytics':navigate('admin-analytics');break;case 'go-admin-ai':navigate('admin-ai');break;case 'go-analytics':navigate('analytics');break;
case 'reset':state=structuredClone(seed);render();toast('нстрационные данные сброшены');break;
case 'open-agent':state.agentId=id;state.agentTab='overview';navigate('agent');break;
case 'new-agent':state.modal={type:'new-agent'};render();break;
case 'create-agent':{const name=val('new-agent-name').trim();if(!name){toast('Укажите название агента');break}if(state.agents.length>=10){toast('Достигнут лимит 10 агентов');break}const type=val('new-agent-type');const next='a'+Date.now();state.agents.push({id:next,name,type,description:'Новый агент. Настройте описание задач.',status:'draft',tags:[],scope:type==='hr'?'HR-отдел':'Команда продаж',connectors:[],prompt:'',last:'Никогда',spent:0,dialogs:0});state.agentId=next;state.agentTab='settings';eventAdd('Создан черновик агента',name);navigate('agent');toast('Черновик создан ');break}
case 'agent-tab':state.agentTab=el.dataset.tab;render();break;case 'agent-integrations':state.agentTab='integrations';render();break;
case 'stop-agent':state.modal={type:'stop-agent',id};render();break;case 'start-agent':state.modal={type:'start-agent',id};render();break;
case 'confirm-stop':{const a=getAgent(state.modal.id);a.status='stopped';eventAdd('Агент остановлен',`Агент: ${a.name} · Ольга К.`, 'human',a.id);state.modal=null;render();toast('Агент остановлен · поля доступны для редактирования');break}
case 'confirm-start':{const a=getAgent(state.modal.id);a.status='active';eventAdd('Агент запущен',`Агент: ${a.name} · `, 'human',a.id);state.modal=null;render();toast('Агент запущен · конфигурация заблокирована');break}
case 'add-connector':state.modal={type:'add-connector'};render();break;
case 'create-connector':{const name=val('connector-name').trim(),type=val('connector-type');if(!name){toast('Укажите название подключения');break}if(state.connectors.length>=10){toast('Достигнут лимит 10 интеграций');break}state.connectors.push({id:'co'+Date.now(),name,type,kind:['CRM','Календарь'].includes(type)?'shared':'exclusive',agentId:null,status:'ok'});state.modal=null;render();toast('Подключение добавлено (, без API)');break}
case 'connector-detail':state.modal={type:'connector',id};render();break;
case 'chat-select':if(state.inboxId!==id){scrollSave();state.inboxId=id;state.journalContext=null;state.showMobileDetails=false;navigate('inbox',{force:true})}break;
case 'takeover-chat':{const c=getChat(id);if(state.scenario==='expired'){toast('Доступен только просмотр');break}c.owner='human';eventAdd('Диалог перехвачен сотрудником',`Ольга К. · ${c.name} · ${c.channel}`,'human',c.agentId);render();toast('Диалог теперь у сотрудника');break}
case 'return-chat':{const c=getChat(id);if(state.scenario==='expired'){toast('Доступен только просмотр');break}c.owner='ai';eventAdd('Диалог возвращён ИИ',`Ольга К. · ${c.name} · ${c.channel}`,'human',c.agentId);render();toast('Диалог возвращён ИИ');break}
case 'send-message':{const text=val('chat-input').trim(),c=getChat();if(!text)return;if(c.owner!=='human'||state.scenario==='expired')return;c.messages.push({by:'human',text,time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})});c.last=text;c.time='Сейчас';eventAdd('Сотрудник ответил клиенту',`Ольга К. · ${c.channel} · ${c.name}`,'human',c.agentId);render();toast('Сообщение добавлено в  (не отправлено в канал)');break}
case 'mobile-ov-tab':state.ovMobileTab=el.dataset.tab;render();break;
case 'test-mode':state.testMode=el.dataset.mode;render();break;
case 'send-test':{const text=val('test-input').trim();if(!text)return;state.testMessages.push({text:'Вы: '+text});if(state.testMode==='live'){state.modal={type:'confirm-test',text};render()}else{state.testMessages.push({text:'ИИ: Симуляция ответа. Внешние операции не выполнялись.'});eventAdd('TEST · симуляция агента',`${getAgent().name} · действие без внешних эффектов`,'test',getAgent().id,'0,00 ₽','0,8 с');render();toast('Тестовый ответ сформирован ()')}break}
case 'approve-test':{const text=state.modal.text;state.testMessages.push({text:'TEST: действие подтверждено пользователем. CRM-операция имитирована, реальные данные не изменены.'});eventAdd('TEST · подтверждена операция CRM',`Ольга К. · ${getAgent().name} · запрос: ${text}`,'test',getAgent().id,'0,00 ₽','1,2 с');state.modal=null;render();toast('Тестовая операция имитирована · отметка в журнале');break}
case 'open-candidate':state.candidateId=id;state.modal={type:'candidate',id};render();break;
case 'candidate-back':state.modal={type:'candidate',id:state.modal.id};render();break;
case 'candidate-reject':state.modal={type:'candidate-reject',id:state.modal.id};render();break;
case 'candidate-reject-final':{const c=getCandidate(state.modal.id);c.stage='Завершено: отказ HR';c.category='possible';eventAdd('HR отклонил кандидатуру',`Ольга К. · ${c.name} · уведомление во внешний канал только в реальном продукте`,'human','a2');state.modal=null;render();toast('Решение HR зафиксировано · без внешней отправки');break}
case 'candidate-accept':{const c=getCandidate(state.modal.id);c.stage='Дальнейший отбор';c.category='review';eventAdd('HR продолжил отбор',`Ольга К. · ${c.name}`,'human','a2');state.modal=null;render();toast('Кандидат переведён на следующий этап');break}
case 'notif-read':{const n=state.notifications.find(n=>n.id===id);if(n)n.read=true;render();toast('Отмечено прочитанным');break}
case 'notif-open':{const n=state.notifications.find(n=>n.id===id);if(n){navigate(n.type==='billing'?'billing':n.type==='action'?'contacts':'inbox')}break}
case 'read-all':state.notifications.forEach(n=>n.read=true);render();break;
case 'save-email':{const addr=val('notify-email').trim();if(!/^\S+@\S+\.\S+$/.test(addr)){toast('Проверьте формат email');break}state.notifyEmail=addr;state.emailVerified=false;state.modal={type:'generic',title:'Подтверждение email · ',desc:'В реальном AIMock на новый адрес уйдёт письмо с одноразовой ссылкой. До подтверждения критические уведомления остаются на старом проверенном адресе. Здесь письмо не отправляется.'};render();break}
case 'manage-sub':openGeneric('Управление подпиской','Продлите подписку, измените тариф или отмените продление. Действующие условия сохраняются до следующего расчётного периода.');break;
case 'topup':openGeneric('Пополнение AI-баланса','Платёж откроется в защищённой форме оплаты.');break;
case 'views':openGeneric('Сохранённые представления','Пользователь может сохранить свои фильтры по типам, тегам и состояниям агентов и диалогов. Группы доступа существуют отдельно от тегов.');break;
case 'upload-knowledge':openGeneric('Загрузка знаний','Загрузка доступна для ресурсов, не используемых активными агентами.');break;
case 'knowledge-details':openGeneric('Зависимость базы знаний','Документ открыт только для просмотра, если связан с активным агентом. Интерфейс покажет всех зависимых агентов и причину блокировки.');break;
case 'roles':openGeneric('Роли и права','Несколько ролей на сотрудника, составные разрешения и ограничение областей ресурсов. Owner управляет полным набором прав.');break;
case 'groups':openGeneric('Группы доступа','Доступ назначается через роли и группы ресурсов, а не автоматически через изменяемые пользовательские теги.');break;
case 'help-topic':openGeneric(el.dataset.title,'Статья с пошаговой инструкцией, скриншотами, поиском и связанными материалами.');break;
case 'modal-close':state.modal=null;render();break;
case 'org-detail':state.adminOrgId=id;state.adminTab='overview';navigate('admin-org-detail');break;
case 'admin-tab':state.adminTab=el.dataset.tab;render();break;
case 'org-block':state.modal={type:'org-block',id};render();break;
case 'org-block-confirm':{const o=state.orgs.find(o=>o.id===state.modal.id);o.status=o.status==='blocked'?'active':'blocked';if(o.status==='blocked')o.running=0;state.modal=null;render();toast('Статус организации изменён только в ');break}
case 'edit-plan':state.modal={type:'edit-plan',id};render();break;
case 'new-plan':state.modal={type:'new-plan'};render();break;
case 'save-plan':{const p=state.plans.find(p=>p.name===state.modal.id);p.price=Math.max(0,Number(val('plan-price'))||0);p.agents=Math.max(1,Number(val('plan-agents'))||1);p.members=Math.max(1,Number(val('plan-members'))||1);p.integrations=Math.max(0,Number(val('plan-integrations'))||0);state.modal=null;render();toast('-тариф обновлён; в продукте требуется публикация версии');break}
case 'create-plan':{const name=val('plan-name').trim();if(!name||state.plans.some(p=>p.name.toLowerCase()===name.toLowerCase())){toast('Укажите уникальное название');break}state.plans.push({name,price:Number(val('plan-price'))||0,agents:10,members:20,integrations:10});state.modal=null;render();toast('Тариф создан в ');break}
case 'new-promo':state.modal={type:'new-promo'};render();break;
case 'create-promo':{const code=val('promo-name').trim().toUpperCase().replace(/[^A-Z0-9_-]/g,'');if(!code||state.promos.some(p=>p.code===code)){toast('Укажите уникальный код');break}state.promos.push({code,discount:Math.max(1,Math.min(100,Number(val('promo-discount'))||15)),clicks:0,signups:0,payments:0});state.modal=null;render();toast('-промокод создан');break}
case 'copy-promo':{const url='https://example.invalid/?promo='+el.dataset.code;if(navigator.clipboard?.writeText){navigator.clipboard.writeText(url).then(()=>toast('Скопирована нстрационная ссылка')).catch(()=>toast(url))}else toast(url);break}
case 'switch-model':state.modal={type:'model',name:el.dataset.model};render();break;
case 'model-confirm':state.adminAiModel=state.modal.name;state.modal=null;render();toast('Активная модель изменена только ');break;
case 'send-support':{const t=val('support-input').trim();if(!t)return;state.supportReplies.push(t);render();toast('Ответ записан в , письмо не отправлено');break}
case 'refund-preview':{const amount=Number(val('refund-amount'))||0;if(amount<=0){toast('Укажите сумму возврата');break}state.modal={type:'refund-preview',id,amount,source:val('refund-source'),reason:val('refund-reason')};render();break}
case 'refund-demo':state.modal=null;render();toast('-заявка на возврат создана · никаких денежных операций');break;
case 'emergency':openGeneric('Аварийная остановка операций','Это приостановит исходящие действия ИИ по всей платформе; операция будет записана в журнал.');break;
default:toast('Не удалось выполнить действие');break}
}
window.addEventListener('popstate',e=>{if(e.state?.aimockV04){state.navTrail=e.state.trail||[];restoreSnapshot(e.state.view)}else if(state.navTrail?.length){restoreSnapshot(state.navTrail.pop())}});
app.addEventListener('scroll',e=>{const el=e.target;if(el.matches?.('.chat-messages'))state.scrollMemory['thread:'+state.activeOrgId+':'+state.inboxId]=el.scrollTop;if(el.matches?.('.chat-scroll'))state.scrollMemory['list:'+state.activeOrgId]=el.scrollTop;if(el.matches?.('.view-stage.flow-view'))state.scrollMemory['view:'+state.page]=el.scrollTop},true);
app.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(el.tagName==='BUTTON')e.preventDefault();runAction(a,el)});
app.addEventListener('change',e=>{const el=e.target;if(el.dataset.change==='scenario'){state.scenario=el.value;render();return}if(el.dataset.change==='inbox-filter'){state.inboxFilter=el.value;render();return}if(el.dataset.connectorId){const c=getConnector(el.dataset.connectorId),a=getAgent(el.dataset.agent);if(a.status==='active'||state.scenario==='expired'){render();toast('Остановите агента перед изменением интеграций');return}const had=a.connectors.includes(c.id);if(el.checked&&!had){if(c.kind==='exclusive'&&c.agentId&&c.agentId!==a.id){render();toast('Это подключение уже занято другим агентом');return}a.connectors.push(c.id);if(c.kind==='exclusive')c.agentId=a.id;eventAdd('Подключение назначено агенту',`${c.name} → ${a.name}`,'human',a.id)}else if(!el.checked&&had){a.connectors=a.connectors.filter(id=>id!==c.id);if(c.kind==='exclusive')c.agentId=null;eventAdd('Подключение отвязано от агента',`${c.name} · ${a.name}`,'human',a.id)}render();toast('Назначения сохранены ');return}if(el.dataset.agentField){const a=getAgent(el.dataset.agent);if(a.status==='active'||state.scenario==='expired'){render();return}let value=el.value;if(el.dataset.agentField==='tags')value=value.split(',').map(x=>x.trim()).filter(Boolean);a[el.dataset.agentField]=value;save();toast('Черновик сохранён автоматически');if(el.dataset.agentField==='name'||el.dataset.agentField==='tags')render()}});
app.addEventListener('input',e=>{const el=e.target;if(el.dataset.input==='inbox-search'){state.inboxQuery=el.value;scrollSave();const caret=el.selectionStart;render();const ref=app.querySelector('[data-input="inbox-search"]');if(ref){ref.focus();ref.setSelectionRange(caret,caret)}return}if(el.dataset.input==='search'){state.search=el.value;const caret=el.selectionStart;render();const ref=app.querySelector('[data-input="search"]');if(ref){ref.focus();ref.setSelectionRange(caret,caret)}}if(el.dataset.input==='helpSearch'){state.helpSearch=el.value;const caret=el.selectionStart;render();const ref=app.querySelector('[data-input="helpSearch"]');if(ref){ref.focus();ref.setSelectionRange(caret,caret)}}});
app.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='chat-input')runAction('send-message',e.target);if(e.key==='Enter'&&e.target.id==='test-input')runAction('send-test',e.target);if(e.key==='Enter'&&e.target.id==='support-input')runAction('send-support',e.target);if(e.key==='Escape'&&state.modal){state.modal=null;render()}if(e.key==='Enter'&&e.target.closest('.agent-card')){const el=e.target.closest('.agent-card');runAction('open-agent',el)}});
