Object.assign(AIMOCK_EN,AIMOCK_V04_EN);

const AIMOCK_EN_PAIRS = Object.entries(AIMOCK_EN).filter(([a,b])=>a.length>5).sort((a,b)=>b[0].length-a[0].length);
function tUI(raw){if(typeof raw!=='string'||!/[А-Яа-яЁё]/.test(raw))return raw;
 const trimmed=raw.trim(); if(!trimmed)return raw;
 let translated=AIMOCK_EN[trimmed];
 if(!translated){translated=trimmed;
  for(const [ru,en] of AIMOCK_EN_PAIRS) if(translated.includes(ru)) translated=translated.split(ru).join(en);
  // generic patterns in status notes, dates, and user-facing counts
  translated=translated.replace(/·\s*пример/g,'').replace(/занят/g,'in use').replace(/(\d+)\s+час(?:а|ов)?/g,'$1 hours').replace(/(\d+)\s+минут(?:ы)?/g,'$1 minutes')
    .replace(/(\d+)\s+агент(?:а|ов)?/g,'$1 agents').replace(/(\d+)\s+сотрудник(?:а|ов)?/g,'$1 members')
    .replace(/(\d+)\s+сообщени(?:й|я|е)/g,'$1 messages');
 }
 const left=raw.match(/^\s*/)?.[0]||'',right=raw.match(/\s*$/)?.[0]||'';
 return left+translated+right;
}
function translateRenderedUI(){if(state.locale!=='en')return;
 const walk=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);
 const nodes=[];while(walk.nextNode())nodes.push(walk.currentNode);
 for(const n of nodes){if(n.parentElement?.closest('script,style'))continue;if(/[А-Яа-яЁё]/.test(n.nodeValue))n.nodeValue=tUI(n.nodeValue)}
 for(const el of app.querySelectorAll('[title],[placeholder],[aria-label],[value]')){
  for(const prop of ['title','placeholder','aria-label'])if(el.hasAttribute(prop))el.setAttribute(prop,tUI(el.getAttribute(prop)));
 }
}
try{if(history.state?.aimockV04){const ss=history.state.view;for(const k of ['page','mode','agentId','agentTab','inboxId','inboxFilter','inboxQuery','journalContext','contactContext','eventContext','activeOrgId'])if(ss&&k in ss)state[k]=ss[k];state.navTrail=history.state.trail||[]}else if(location.hash.startsWith('#/')){const seg=decodeURIComponent(location.hash.slice(2)).split('/');if(seg[0]==='workspace'){state.mode='workspace';if(seg[1]){state.page=seg[1];if(seg[1]==='inbox'&&seg[2])state.inboxId=seg[2];if(seg[1]==='agent'&&seg[2])state.agentId=seg[2];if(seg[1]==='contact-detail'&&seg[2])state.contactContext=seg[2];if(seg[1]==='journal'&&seg[2]==='conversation')state.journalContext=seg[3]||null;if(seg[1]==='journal-event'&&seg[2]==='event')state.eventContext=seg[3]||null}}else if(seg[0]==='admin'){state.mode='admin';state.page='admin-'+(seg[1]||'overview');if(seg[1]==='org-detail'&&seg[2])state.adminOrgId=seg[2]}}}catch(e){}
render();writeHistory(true);